	IF ' ##class(%File).DirectoryExists(direc)
	 {
			 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ direc)
			 Do ##class(%File).CreateDirectoryChain(direc)
		     set tStat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup($get(%session.Data("UsNm")), $get(%session.Data("PsWd")))
	 }

	set file = ##class(%File).%New(fileNm)
	if ##class(%File).Exists(fileNm)
	{
		Do ..searchComponent(fileNm, comp)
		set stat = file.Open("W:/APPEND")
		set retStr = "Appended to DeploymentPackage file: " _ fileNm
	}
	else
	{		
		set svnDepPkg = ##class(IHC.ITF.SrcCtrlPkg.CreateDeploymentPackage).%New()
		Do svnDepPkg.GetDeploymentPackageFromSvn(AIKB _".txt",$get(%session.Data("UsNm")), $get(%session.Data("PsWd")))

		if ##class(%File).Exists(fileNm)
		{
			Do ..searchComponent(fileNm, comp)
			set stat = file.Open("W:/APPEND")
			set retStr = "Appended to DeploymentPackage file from SVN: " _ fileNm
		}
		else
		{
			set stat = file.Open("WN")
			set retStr = "Created DeploymentPackage file: " _ fileNm
		}
	}
	if ($$$ISOK(stat))
	{
    	Do file.WriteLine("# Deployment Package AIKB: " _ AIKB)
