  set wFileNm = fileNm _ "-New"

  set file = ##class(%File).%New(fileNm)
  set retStr = ""
	if ##class(%File).Exists(fileNm)
	{
		set stat = file.Open("R")
		set retStr = "Read DeploymentPackage file: " _ fileNm _ ", stat: " _ stat
	}
	set fileSize = file.Size
	set searchcompNm = "Component  #$# " _ compNm
	set compInd = file.FindAt(1, searchcompNm)
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Found: " _ compNm _ " at " _ compInd _" of " _ fileSize)
	if (compInd > 0)
	{
  	    set wFile = ##class(%File).%New(wFileNm)
		set stat = wFile.Open("WN")
		set rLen = 0
		set comment = 0
		Do file.MoveTo(0)

		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( rLen _ " < " _ fileSize)

		WHILE ( rLen < fileSize)
		{
			set len = 100
			set str = file.ReadLine(.len, .sc, .eol)

			set rLen = rLen + len
			if ($L(str) > 0)
			{

				if ( (str [ "Deployment Package AIKB") && (comment = 1))
				{
					set comment = 0
				}

				if ( (str [ searchcompNm) || (comment = 1))
				{
					Do wFile.WriteLine("#" _str)
					set comment = 1
				}
				else
				{
					Do wFile.WriteLine(str)
				}
			}
			if ( ($$$ISERR(sc)) || (eol = 1) || (len <= 0))
			{
			    QUIT
			}

		}
		Do wFile.Close()
		Do file.Close()
		Do ##class(%File).CopyFile(wFileNm, fileNm, 1)
		Do ##class(%File).Delete(wFileNm)
	}
	else
	{
		Do file.Close()
	}

